{QuestionName=Basic Operations in Lists, testcase=Find Numbers with Even Number of Digits_ValidScenario, PythonCode=def findNumbers(nums):
    count_even = 0

    for num in nums:
        # Convert number to string and check the length
        if len(str(num)) % 2 == 0:
            count_even += 1

    return count_even

# Example usage
